import{R as a,e,f as n,U as o}from"./chunks/framework.ywem4qy5.js";const d=JSON.parse('{"title":"Snaptcha","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/captchas/snaptcha.md","filePath":"integrations/captchas/snaptcha.md","lastUpdated":1775908585000}'),s={name:"integrations/captchas/snaptcha.md"};function r(i,t,l,h,p,c){return e(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="snaptcha" tabindex="-1">Snaptcha <a class="header-anchor" href="#snaptcha" aria-label="Permalink to &quot;Snaptcha&quot;">​</a></h1><p>Follow the below steps to use Snaptcha with Formie.</p><h3 id="step-1-install-and-configure-snaptcha" tabindex="-1">Step 1. Install and configure Snaptcha <a class="header-anchor" href="#step-1-install-and-configure-snaptcha" aria-label="Permalink to &quot;Step 1. Install and configure Snaptcha&quot;">​</a></h3><ol><li>Install the <a href="https://plugins.craftcms.com/snaptcha" target="_blank" rel="noreferrer">Snaptcha plugin</a> for Craft CMS.</li><li>Configure Snaptcha itself using that plugin&#39;s settings and setup instructions.</li></ol><h3 id="step-2-open-the-captcha-settings" tabindex="-1">Step 2. Open the Captcha Settings <a class="header-anchor" href="#step-2-open-the-captcha-settings" aria-label="Permalink to &quot;Step 2. Open the Captcha Settings&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Captchas</strong>.</li><li>Select <strong>Snaptcha</strong> in the left-hand sidebar.</li><li>Turn on <strong>Enabled</strong>.</li><li>Save the captcha settings.</li></ol><h3 id="step-3-form-setting" tabindex="-1">Step 3. Form Setting <a class="header-anchor" href="#step-3-form-setting" aria-label="Permalink to &quot;Step 3. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to protect.</li><li>Enable <strong>Snaptcha</strong> for that form.</li><li>For multi-page forms, turn on <strong>Show on All Pages</strong> if Snaptcha should run on every page instead of only the final submit step.</li><li>Save the form.</li></ol><p>Formie reads the Snaptcha field name and token value from the Snaptcha plugin, so there are no extra keys to enter in Formie itself.</p>',9)])])}const f=a(s,[["render",r]]);export{d as __pageData,f as default};
